(function(){
  var nav=document.querySelector('header.nav'); if(!nav) return;
  if(window.ic) window.ic(nav);
  var btns=[].slice.call(nav.querySelectorAll('.nl[data-m]')),panels={};
  [].forEach.call(nav.querySelectorAll('.mega'),function(p){panels[p.getAttribute('data-m')]=p;});
  var cur=null,t1,t2,fine=window.matchMedia('(any-hover:hover)');
  function hl(p){var l=p.querySelector('.sv-wrap');if(!l)return;var a=l.querySelector('.sv.on'),h=l.querySelector('.sv-hl');if(a&&h){h.style.height=a.offsetHeight+'px';h.style.transform='translateY('+a.offsetTop+'px)';}}
  function suite(p,i){[].forEach.call(p.querySelectorAll('.sv'),function(b,k){b.classList.toggle('on',k==i);b.setAttribute('aria-selected',k==i?'true':'false');});
    [].forEach.call(p.querySelectorAll('.mg-p'),function(s,k){s.classList.toggle('on',k==i);});hl(p);}
  function close(){clearTimeout(t1);cur=null;nav.classList.remove('mx');
    btns.forEach(function(b){b.setAttribute('aria-expanded','false');});
    Object.keys(panels).forEach(function(k){panels[k].classList.remove('on');});}
  function open(m){clearTimeout(t2);if(cur===m)return;var was=cur;close();cur=m;var p=panels[m];
    var mn=document.getElementById('mnav');if(mn&&!mn.hidden){mn.hidden=true;var mb=document.getElementById('mbtn');if(mb)mb.setAttribute('aria-expanded','false');}
    nav.classList.add('mx');p.classList.add('on');
    btns.forEach(function(b){b.setAttribute('aria-expanded',b.getAttribute('data-m')===m?'true':'false');});
    if(p.querySelector('.sv'))suite(p,0);
    requestAnimationFrame(function(){hl(p);});}
  btns.forEach(function(b){var m=b.getAttribute('data-m');
    b.addEventListener('pointerenter',function(ev){if(ev.pointerType==='touch'||!fine.matches)return;clearTimeout(t2);clearTimeout(t1);open(m);});
    b.addEventListener('pointerleave',function(ev){if(ev.pointerType==='touch')return;clearTimeout(t1);t2=setTimeout(close,220);});
    b.addEventListener('click',function(e){if(cur===m&&(!fine.matches||e.detail===0)){close();return;}open(m);
      if(e.detail===0){var f=panels[m].querySelector('.sv.on,.it');if(f)setTimeout(function(){f.focus();},60);}});});
  nav.addEventListener('mouseenter',function(){clearTimeout(t2);});
  nav.addEventListener('mouseleave',function(){clearTimeout(t1);t2=setTimeout(close,320);});
  [].forEach.call(nav.querySelectorAll('.brand,.nav-end,.nl:not([data-m])'),function(el){el.addEventListener('mouseenter',function(){clearTimeout(t1);if(cur){clearTimeout(t2);t2=setTimeout(close,140);}});});
  Object.keys(panels).forEach(function(k){var p=panels[k];
    [].forEach.call(p.querySelectorAll('.sv'),function(b){var i=+b.getAttribute('data-i'),h;
      b.addEventListener('mouseenter',function(){if(!fine.matches)return;h=setTimeout(function(){suite(p,i);},50);});
      b.addEventListener('mouseleave',function(){clearTimeout(h);});
      b.addEventListener('focus',function(){suite(p,i);});
      b.addEventListener('click',function(){suite(p,i);});
      b.addEventListener('keydown',function(e){var all=[].slice.call(p.querySelectorAll('.sv')),n=all.indexOf(b);
        if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();var t=all[(n+(e.key==='ArrowDown'?1:-1)+all.length)%all.length];t.focus();}});});
    p.addEventListener('mousemove',function(e){var it=e.target.closest&&e.target.closest('.it');if(!it)return;var r=it.getBoundingClientRect();it.style.setProperty('--mx',(e.clientX-r.left)+'px');it.style.setProperty('--my',(e.clientY-r.top)+'px');});
    p.addEventListener('mouseenter',function(){clearTimeout(t2);});p.addEventListener('click',function(e){if(e.target.closest('a'))close();});});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&cur){var b=nav.querySelector('.nl[data-m="'+cur+'"]');close();if(b)b.focus();}});
  document.addEventListener('click',function(e){if(cur&&!nav.contains(e.target))close();});
  window.addEventListener('resize',function(){if(cur)hl(panels[cur]);if(window.innerWidth<=1000)close();});
  // mobile accordion
  var acc=[].slice.call(nav.querySelectorAll('.mnav .ma'));
  acc.forEach(function(a){a.addEventListener('click',function(){var o=a.getAttribute('aria-expanded')==='true';acc.forEach(function(x){x.setAttribute('aria-expanded','false');});a.setAttribute('aria-expanded',o?'false':'true');});});
})();

(function(){
  var RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function $(s,r){return (r||document).querySelector(s)}
  function $$(s,r){return [].slice.call((r||document).querySelectorAll(s))}
  /* reveal */
  var rv=$$('.rv');
  if('IntersectionObserver' in window){var o=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');o.unobserve(e.target)}})},{threshold:.12});rv.forEach(function(el){o.observe(el)})}else rv.forEach(function(el){el.classList.add('in')});
  function onView(el,fn){if(!el)return;if(!('IntersectionObserver' in window)){fn();return}var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){io.disconnect();fn()}},{threshold:.25});io.observe(el)}
  /* call timer + controls + device ring */
  var tm=$('#ptTimer');if(tm&&!RM){var s=252;setInterval(function(){if(document.hidden)return;s++;var m=Math.floor(s/60),x=s%60;tm.textContent=(m<10?'0':'')+m+':'+(x<10?'0':'')+x},1000)}
  function rot(sel,cls,ms){var els=$$(sel),i=0;if(!els.length||RM)return;setInterval(function(){if(document.hidden)return;els.forEach(function(e){e.classList.remove(cls)});els[i%els.length].classList.add(cls);i++},ms)}
  rot('.pt-ctrls span','lit',1300);rot('.pt-dev','ring',2400);
  /* chat sequences */
  function seq(root,items,typing,gap,hold,keep){keep=keep||0;
    items=$$(items,root);var ty=typing?$(typing,root):null;if(!items.length)return;
    if(RM){items.forEach(function(m){m.classList.add('on')});return}
    var timers=[];function T(f,ms){timers.push(setTimeout(f,ms))}
    items.forEach(function(m,i){if(i<keep)m.classList.add('on')});
    function run(){
      items.forEach(function(m,i){m.classList.toggle('on',i<keep)});var t=400;
      items.forEach(function(m,i){
        if(i<keep)return;var out=m.classList.contains('o')||m.classList.contains('a');
        if(out&&ty){T(function(){ty.classList.add('on')},t);t+=900;T(function(){ty.classList.remove('on')},t)}
        T(function(){m.classList.add('on')},t);t+=gap;
      });
      T(run,t+hold);
    }
    onView(root,run);
  }
  var ph=$('.pt-phone');if(ph){var tp=$('.pt-typing',ph);var msgs=$('.pt-msgs',ph);
    // keep typing indicator last
    seq(ph,'.pt-m','.pt-typing',1500,4200,2);
  }
  var ai=$('.pt-ai');if(ai)seq(ai,'.pt-b',null,1700,5000,2);
  /* counters */
  $$('.pt-count').forEach(function(el){var to=+el.getAttribute('data-to'),dec=+(el.getAttribute('data-dec')||0);if(RM){return}
    onView(el,function(){var st=performance.now(),dur=1400;(function f(n){var k=Math.min(1,(n-st)/dur),v=to*(1-Math.pow(1-k,3));el.textContent=dec?v.toFixed(dec):Math.round(v);if(k<1)requestAnimationFrame(f)})(st)})});
  /* tabs */
  var tabs=$$('.ptab'),pns=$$('.pt-pn');
  function show(i){tabs.forEach(function(t,k){t.setAttribute('aria-selected',k===i?'true':'false');t.tabIndex=k===i?0:-1});pns.forEach(function(p,k){p.classList.toggle('on',k===i)})}
  tabs.forEach(function(t,i){t.addEventListener('click',function(){show(i)});t.addEventListener('keydown',function(e){var n=tabs.length;if(e.key==='ArrowRight'){show((i+1)%n);tabs[(i+1)%n].focus()}if(e.key==='ArrowLeft'){show((i+n-1)%n);tabs[(i+n-1)%n].focus()}})});
  /* faq */
  $$('.fq').forEach(function(q){var b=$('button',q);b.addEventListener('click',function(){var o=q.classList.contains('open');$$('.fq.open').forEach(function(x){x.classList.remove('open');$('button',x).setAttribute('aria-expanded','false')});if(!o){q.classList.add('open');b.setAttribute('aria-expanded','true')}})});
  /* form (demo only) */
  var f=$('#ptForm');if(f)f.addEventListener('submit',function(e){e.preventDefault();var ok=$('#ptOk');if(ok){ok.style.display='block'}});
  /* shared: mobile nav, footer wordmark, story index */
  var mb=$('#mbtn'),mn=$('#mnav');
  if(mb&&mn){mb.addEventListener('click',function(){var op=mn.hidden;mn.hidden=!op;mb.setAttribute('aria-expanded',String(op))});$$('#mnav a').forEach(function(a){a.addEventListener('click',function(){mn.hidden=true;mb.setAttribute('aria-expanded','false')})})}
  var wm=$('#wm');if(wm)onView(wm,function(){wm.classList.add('in')});
  $$('.story').forEach(function(x,i){x.style.setProperty('--i',i%3)});
  var pf=$('.proof');if(pf)onView(pf,function(){$$('[data-count]',pf).forEach(function(el){var to=+el.dataset.count,dec=+el.dataset.dec||0,st=performance.now();(function f(n){var k=Math.min(1,(n-st)/1600),v=to*(1-Math.pow(1-k,3));el.textContent=dec?v.toFixed(dec):Math.round(v).toLocaleString('en-US');if(k<1)requestAnimationFrame(f)})(st)})});
})();

/* stories: one looping row; enough inert copies that half the track is always wider than the row */
(function(){var row=document.getElementById("storyRow");if(!row)return;
  var cards=[].slice.call(row.children),track=document.createElement("div");track.className="mq-track";
  cards.forEach(function(c){c.classList.remove("rv");c.classList.add("in");track.appendChild(c)});
  row.appendChild(track);row.classList.add("mq");
  var cw=(cards[0].getBoundingClientRect().width||360)+16,setW=cw*cards.length,groups=Math.ceil(1800/setW)*2;
  for(var g=1;g<groups;g++)cards.forEach(function(c){var k=c.cloneNode(true);k.setAttribute("aria-hidden","true");k.setAttribute("inert","");track.appendChild(k)});
  track.style.setProperty("--mq-dur",Math.round(setW*(groups/2)/47)+"s");
})();
/* placeholder links should not jump to the top */
document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest('a[href="#"]');if(a)e.preventDefault()});

/* Motion (motion.dev): hero entrance, one-time scroll reveals, press feedback. Skipped for reduced motion. */
(function(){var root=document.documentElement;function done(){root.classList.remove('m-pre')}
  var M=window.Motion;
  if(!M||matchMedia('(prefers-reduced-motion: reduce)').matches){done();return}
  var animate=M.animate,inView=M.inView,stagger=M.stagger,press=M.press,EASE=[.22,1,.36,1];
  function clean(els){return function(){setTimeout(function(){els.forEach(function(el){el.style.opacity='';el.style.transform=''})},60)}}
  var hero=[].slice.call(document.querySelectorAll('.hero-copy > *'));
  if(hero.length){hero.forEach(function(el){el.style.opacity='0'});
    animate(hero,{opacity:[0,1],transform:['translateY(22px)','translateY(0px)']},{duration:.8,ease:EASE,delay:stagger(.08,{startDelay:.05})}).then(clean(hero))}
  requestAnimationFrame(done);setTimeout(function(){hero.forEach(function(el){if(+getComputedStyle(el).opacity<1){el.style.opacity="";el.style.transform=""}})},4000);
  var seen=new WeakSet();
  function reveal(els,y){
    els=els.filter(function(el){if(seen.has(el)||el.closest('.mega,.mnav,.hero-copy'))return false;seen.add(el);return true});
    if(!els.length)return;y=y||24;
    els.forEach(function(el){el.classList.remove('rv');el.style.opacity='0';el.style.transform='translateY('+y+'px)'});
    inView(els[0].parentElement||els[0],function(){
      animate(els,{opacity:[0,1],transform:['translateY('+y+'px)','translateY(0px)']},{duration:.7,ease:EASE,delay:stagger(.07)}).then(clean(els));
    },{amount:.15});
  }
  [].forEach.call(document.querySelectorAll('section .sec-head'),function(h){reveal([h],18)});
  var groups=new Map();
  [].forEach.call(document.querySelectorAll('.pt-stage > *, .pt-ai, .pt-4 .pt-f, .pt-ban .ban, .fq, .fq-side, .cta .form'),function(el){var k=el.parentElement;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(el)});
  groups.forEach(function(els){reveal(els,28)});
  press('.btn, .nl, .ov, .ptab',function(el){
    animate(el,{scale:.96},{type:'spring',stiffness:600,damping:30});
    return function(){animate(el,{scale:1},{type:'spring',stiffness:500,damping:22}).then(function(){el.style.transform=''})};
  });
})();

/* Team Messaging page: live demos (chat + huddle, feature tabs, Slack bridge, presence, comparison, team tabs).
   Autoplay runs only while a demo is on screen and the tab is visible; reduced motion gets static end states. */
(function(){
  var RM=matchMedia('(prefers-reduced-motion: reduce)').matches,M=window.Motion,EASE=[.22,1,.36,1];
  function $(s,r){return (r||document).querySelector(s)}
  function $$(s,r){return [].slice.call((r||document).querySelectorAll(s))}
  function esc(t){return String(t).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
  function sleep(ms){return new Promise(function(r){setTimeout(r,ms)})}
  function pad(n){return (n<10?'0':'')+n}
  function ic(el){if(window.ic)window.ic(el)}
  function watch(el){var vis=false;if(!el)return function(){return false};
    if(!('IntersectionObserver' in window))return function(){return !document.hidden};
    new IntersectionObserver(function(es){vis=es[0].isIntersecting},{threshold:.15}).observe(el);
    return function(){return vis&&!document.hidden}}
  async function until(vis){while(vis&&!vis())await sleep(250)}
  function enter(el){if(M&&!RM)M.animate(el,{opacity:[0,1],transform:['translateY(10px)','translateY(0px)']},{duration:.45,ease:EASE}).then(function(){el.style.opacity='';el.style.transform=''})}
  function msgEl(m){
    var d=document.createElement('div');d.className='tm-m';
    d.innerHTML='<span class="av '+m.c+'">'+m.i+'</span><div class="tm-bd"><div class="meta"><b>'+esc(m.n)+'</b><small>'+m.t+'</small></div><p>'+esc(m.x)+'</p>'+
      (m.r?'<div class="rx">'+m.r.map(function(e,i){return '<span style="animation-delay:'+(.5+i*.15)+'s">'+e+'</span>'}).join('')+'</div>':'')+'</div>';
    return d}

  /* ---------- hero: chat that becomes a huddle ---------- */
  (function(){
    var box=$('#tmMsgs');if(!box)return;
    var hud=$('#tmHuddle'),join=$('#tmJoin'),hn=$('#tmHn'),un=$('#tmUnread'),jt=$('span',join);
    var A={n:'Priya S.',i:'PS',c:'c1',t:'10:42',x:'Quick one: Sarah at Acme is asking about a multi-year discount on the renewal.',r:['👍','🎉']};
    var B={n:'Daniel O.',i:'DO',c:'c4',t:'10:45',x:'I have her contract open. Want to huddle?'};
    function sys(){var d=document.createElement('div');d.className='tm-sys';d.innerHTML='<i data-i="video"></i>Daniel O. started a huddle';box.appendChild(d);ic(d);return d}
    function live(on){hud.classList.toggle('on',on);join.classList.toggle('live',on);jt.textContent=on?'In huddle':'Join huddle'}
    function fmt(s){return pad(Math.floor(s/60))+':'+pad(s%60)}
    if(RM){box.appendChild(msgEl(A));box.appendChild(msgEl(B));sys();live(true);hn.textContent='2 people · 00:27';return}
    var vis=watch($('#tmApp'));
    (async function(){for(;;){
      box.innerHTML='';live(false);if(un)un.style.visibility='';await until(vis);await sleep(600);
      var a=msgEl(A);box.appendChild(a);enter(a);await sleep(1700);
      var ty=document.createElement('div');ty.className='tm-typing';ty.innerHTML='<i></i><i></i><i></i>';box.appendChild(ty);enter(ty);await sleep(1200);ty.remove();
      var b=msgEl(B);box.appendChild(b);enter(b);if(un)un.style.visibility='hidden';await sleep(1500);
      var s=sys();enter(s);live(true);var sec=27;hn.textContent='2 people · '+fmt(sec);
      for(var k=0;k<6;k++){await sleep(1000);sec++;hn.textContent='2 people · '+fmt(sec)}
      await sleep(1800)}})();
  })();

  /* ---------- feature tabs ---------- */
  (function(){
    var tabs=$$('.tm-ft'),panels=$$('.tm-fp');if(!tabs.length)return;
    function show(i,focus){
      tabs.forEach(function(t,k){t.classList.toggle('on',k===i);t.setAttribute('aria-selected',k===i?'true':'false');t.tabIndex=k===i?0:-1});
      panels.forEach(function(p,k){p.hidden=k!==i});
      var p=panels[i];if(M&&!RM)M.animate(p,{opacity:[0,1],transform:['translateY(10px)','translateY(0px)']},{duration:.4,ease:EASE}).then(function(){p.style.opacity='';p.style.transform=''});
      if(focus)tabs[i].focus()}
    tabs.forEach(function(t,i){t.addEventListener('click',function(){show(i)});
      t.addEventListener('keydown',function(e){var n=tabs.length;if(e.key==='ArrowDown'||e.key==='ArrowRight'){e.preventDefault();show((i+1)%n,true)}if(e.key==='ArrowUp'||e.key==='ArrowLeft'){e.preventDefault();show((i+n-1)%n,true)}})});
  })();

  /* ---------- Slack bridge ---------- */
  (function(){
    var sl=$('#brSl'),uc=$('#brUc'),sync=$('#brSync');if(!sl||!uc)return;
    var P=[{src:'uc',n:'Priya Sharma',i:'PS',c:'c1',x:'The renewal draft is ready.',file:'acme-renewal.pdf'},
           {src:'sl',n:'Mia Chen',i:'MC',c:'c5',x:'Perfect, reviewing before the call.'},
           {src:'uc',n:'Daniel Reyes',i:'DR',c:'c4',x:'Call with Sarah is at 3 pm, joining from here.'}];
    function add(box,m,from){
      var d=document.createElement('div');d.className='bmsg';
      d.innerHTML='<span class="av '+m.c+'">'+m.i+'</span><div><b>'+esc(m.n)+'</b>'+(from?'<span class="sy">Synced from '+from+'</span>':'')+'<p>'+esc(m.x)+'</p>'+(m.file?'<span class="tm-file"><i data-i="file"></i><b>'+m.file+'</b></span>':'')+'</div>';
      box.appendChild(d);ic(d);while(box.children.length>3)box.firstElementChild.remove()}
    function both(m,anim){var a=m.src==='uc'?uc:sl,b=m.src==='uc'?sl:uc;add(a,m,'');add(b,m,m.src==='uc'?'Team Chat':'Slack')}
    if(RM){P.forEach(function(m){both(m)});return}
    var vis=watch($('.tm-br-vis'));
    (async function(){for(;;){
      sl.innerHTML='';uc.innerHTML='';await until(vis);await sleep(500);
      for(var i=0;i<P.length;i++){var m=P[i],src=m.src==='uc'?uc:sl,dst=m.src==='uc'?sl:uc;
        add(src,m,'');await sleep(700);sync.classList.remove('pulse');void sync.offsetWidth;sync.classList.add('pulse');
        add(dst,m,m.src==='uc'?'Team Chat':'Slack');await sleep(1700)}
      await sleep(3200)}})();
  })();

  /* ---------- presence ---------- */
  (function(){
    var root=$('#tmPres');if(!root)return;
    var ST=[{chip:'On a call',by:['phone','A call connected'],note:['chat','Mentions only'],until:['clock','When the call ends'],msg:'Aisha is on a call. Chat is fine, she will see mentions.',now:55,act:'0'},
            {chip:'In a meeting',by:['cal','Calendar event'],note:['chat','Mentions only'],until:['clock','11:00 am'],msg:'Aisha is in a meeting. Mentions will wait until it ends.',now:18,act:'1'},
            {chip:'Focus time',by:['eye','Focus block'],note:['zap','Urgent only'],until:['clock','4:00 pm'],msg:'Aisha is focusing. Only urgent messages will come through.',now:80,act:'2'},
            {chip:'At my desk',by:['pin','Back at the desk'],note:['chat','All notifications'],until:['clock','5:00 pm'],msg:'Aisha is available. Go ahead and message her.',now:68,act:null}];
    var btns=$$('#prSeg button'),segs=$$('.tm-day .tm-sg'),cur=0,auto=!RM;
    function put(id,ico,txt){var el=$(id);el.innerHTML='<i data-i="'+ico+'"></i>'+esc(txt);ic(el)}
    function set(i){cur=i;var s=ST[i];root.setAttribute('data-st',i);
      btns.forEach(function(b,k){b.classList.toggle('on',k===i)});
      $('#prChip').textContent=s.chip;$('#prChip2').textContent=s.chip;
      put('#prBy',s.by[0],s.by[1]);put('#prNote',s.note[0],s.note[1]);put('#prUntil',s.until[0],s.until[1]);
      var m=$('#prMsg');m.textContent=s.msg;
      segs.forEach(function(g){g.classList.toggle('act',g.getAttribute('data-k')===s.act)});
      $('#prNow').style.left=s.now+'%';
      if(M&&!RM)M.animate($('#prBan'),{opacity:[.3,1],transform:['translateY(4px)','translateY(0px)']},{duration:.35,ease:EASE}).then(function(){$('#prBan').style.opacity='';$('#prBan').style.transform=''})}
    btns.forEach(function(b){b.addEventListener('click',function(){auto=false;set(+b.getAttribute('data-s'))})});
    set(0);
    if(RM)return;
    var vis=watch(root);
    (async function(){while(auto){await until(vis);await sleep(3600);if(!auto)break;await until(vis);set((cur+1)%ST.length)}})();
  })();

  /* ---------- before / after ---------- */
  (function(){
    var root=$('#tmBa');if(!root)return;
    var o=$$('.old li',root),n=$$('.new li',root),b1=$('#baB1'),b2=$('#baB2'),t1=$('#baT1'),t2=$('#baT2'),run=0;
    function done(li){li.classList.add('done')}
    function clock(sec){return Math.floor(sec/60)+':'+pad(Math.round(sec%60))}
    function fin(){o.concat(n).forEach(done);b1.style.transition='none';b2.style.transition='none';b1.style.width='100%';b2.style.width='100%';t1.textContent='~4 minutes';t2.textContent='~30 seconds'}
    async function play(){
      var g=++run;o.concat(n).forEach(function(li){li.classList.remove('done')});
      b1.style.transition='none';b2.style.transition='none';b1.style.width='0';b2.style.width='0';t1.textContent='0:00';t2.textContent='0:00';
      void b1.offsetWidth;await sleep(120);if(g!==run)return;
      b1.style.transition='width 5s linear';b2.style.transition='width .7s linear';b1.style.width='100%';b2.style.width='100%';
      var t0=Date.now();
      n.forEach(function(li,i){setTimeout(function(){if(g===run)done(li)},120+i*230)});
      o.forEach(function(li,i){setTimeout(function(){if(g===run)done(li)},150+i*1000)});
      while(g===run&&Date.now()-t0<5200){var e=Date.now()-t0;t1.textContent=clock(Math.min(240,e/5000*240));t2.textContent=clock(Math.min(30,e/700*30));await sleep(70)}
      if(g===run){t1.textContent='~4 minutes';t2.textContent='~30 seconds'}}
    $('#baReplay').addEventListener('click',play);
    if(RM||!('IntersectionObserver' in window)){fin();return}
    var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){io.disconnect();play()}},{threshold:.4});io.observe(root);
  })();

